/*Table structure for table `actuator` */

DROP TABLE IF EXISTS `actuator`;

CREATE TABLE `actuator` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `greenhouse_id` bigint(20) NOT NULL COMMENT '所属温室ID',
  `actuator_type` varchar(50) NOT NULL COMMENT '设备类型: irrigation/supplemental_light/ventilation/co2_generator',
  `model` varchar(100) DEFAULT NULL COMMENT '型号',
  `device_sn` varchar(100) DEFAULT NULL COMMENT '设备序列号',
  `status` varchar(20) NOT NULL DEFAULT 'running' COMMENT '状态: running/stopped',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_actuator_type` (`actuator_type`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8 COMMENT='执行设备表';

