/*Table structure for table `ai_decision_record` */

DROP TABLE IF EXISTS `ai_decision_record`;

CREATE TABLE `ai_decision_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `greenhouse_id` bigint(20) NOT NULL COMMENT '温室ID',
  `problem` varchar(500) DEFAULT NULL COMMENT '问题描述',
  `recommendation` varchar(500) DEFAULT NULL COMMENT '推荐操作',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '置信度',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态: pending/adopted/rejected',
  `execution_result` varchar(255) DEFAULT NULL COMMENT '执行结果',
  `generated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `adopted_at` datetime DEFAULT NULL COMMENT '采纳时间',
  PRIMARY KEY (`id`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COMMENT='AI决策记录表';

/*Data for the table `ai_decision_record` */

insert  into `ai_decision_record`(`id`,`greenhouse_id`,`problem`,`recommendation`,`confidence`,`status`,`execution_result`,`generated_at`,`adopted_at`) values (1,1,'1号温室 光照不足(当前80.7)','当前光照不足，补光设备已在运行但未达要求，建议检查并提升补光强度至番茄结果期所需的20000勒克斯以上，同时可适当降低通风以减少CO₂逸散，其它设备保持运行。','0.9000','adopted','已自动开启设备: SN-LED-001','2026-06-17 20:15:32','2026-06-17 20:26:29'),(2,1,'1号温室 温度过高(当前32.4)','立即关闭补光灯(SN-LED-001)和CO2发生器(SN-CO2G-001)以减少热源；保持通风扇(SN-FAN-001)全开强制降温；可适当延长灌溉(SN-IRR-001)运行进行微雾蒸发降温，并检查温室外遮阳是否展开。温度应尽快降至25-28℃。','0.9500','adopted','设备已在运行中','2026-06-17 20:35:45','2026-06-17 20:36:59'),(3,1,'1号温室 CO2浓度过高(当前887.0)','立即停止CO₂发生器SN-CO2G-001运行，保持通风扇SN-FAN-001全速运行以加速排出过量CO₂，补光灯SN-LED-001和灌溉系统SN-IRR-001可维持当前状态。待浓度降至400-500ppm后，再根据实际需求调整CO₂施放策略。','0.9500','adopted','设备已在运行中','2026-06-17 20:35:50','2026-06-17 20:37:23'),(4,1,'1号温室 光照不足(当前3.0)','当前补光灯已在运行以应对光照不足告警，建议保持所有设备开启，密切监测光照强度，必要时可增加补光时长或强度，同时注意温湿度与CO₂浓度配合。','0.8500','adopted','已自动开启设备: SN-LED-001','2026-06-17 20:35:59','2026-06-17 20:44:48'),(5,1,'1号温室 CO2浓度过高(当前662.0)','立即停止CO2发生器(SN-CO2G-001)以遏制CO2浓度上升；保持通风设备(SN-FAN-001)运行，必要时可提高风速加速排出过量CO2；补光与灌溉设备维持当前状态，暂不调整，但需密切监测温室内温湿度变化。','0.9300','adopted','设备已在运行中','2026-06-17 20:48:12','2026-06-17 20:48:42'),(6,1,'1号温室 光照不足(当前65.7)','光照不足，当前补光灯SN-LED-001虽运行但仍不足，建议将其功率调至最大或延长补光时间至每日14-16小时，并检查灯罩清洁度以提升光照强度。其他设备保持当前运行状态，暂不调整。','0.9000','adopted','设备已在运行中','2026-06-17 20:48:23','2026-06-17 21:16:23'),(7,2,'2号温室 湿度过低(当前33.8)','当前湿度33.8%远低于开花期黄瓜适宜范围（60-80%），应立即加强增湿。保持灌溉系统运行，并建议提高灌溉频率或延长时间；关闭通风设备以减少温室水分散失；补光灯可维持运行，但需注意其产热可能导致相对湿度进一步下降，可结合喷淋快速增湿；CO2发生器可保持运行，其燃烧副产少量水汽有助于增湿。','0.9000','pending',NULL,'2026-06-17 20:52:25',NULL),(8,2,'2号温室 CO2浓度过高(当前838.0)','立即关闭CO2发生器(SN-CO2G-002)，保持通风(SN-FAN-002)最大转速运行，暂停补光灯以减少温升，监测CO2浓度至400-600ppm适宜范围后再调整。灌溉可维持现状。','0.9300','adopted','设备已在运行中','2026-06-17 20:52:29','2026-06-17 20:53:08'),(9,2,'2号温室 光照不足(当前32.0)','当前光照不足，请保持补光设备(supplemental_light)全力运行，并考虑增加补光时长或强度，其他设备可维持现有状态。','0.9000','pending',NULL,'2026-06-17 20:52:38',NULL),(10,1,'1号温室 光照不足（当前值: 29.1）','增加补光灯SN-LED-001的功率或延长开启时间，以提升光照强度至番茄结果期适宜水平（如200-300 μmol/m²/s），预期效果是缓解光照不足，促进光合作用和果实发育。','0.9000','pending',NULL,'2026-06-17 21:19:23',NULL);

/*Table structure for table `ai_service_config` */

DROP TABLE IF EXISTS `ai_service_config`;

CREATE TABLE `ai_service_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `service_type` varchar(50) NOT NULL,
  `service_name` varchar(100) NOT NULL,
  `base_url` varchar(255) NOT NULL,
  `script_path` varchar(500) NOT NULL,
  `extra_args` varchar(500) DEFAULT '',
  `default_gate` varchar(50) DEFAULT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '0',
  `health_path` varchar(100) DEFAULT '/health',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `managed` tinyint(1) NOT NULL DEFAULT '0',
  `greenhouse_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_service_type` (`service_type`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8;

