/*Table structure for table `alert_record` */

DROP TABLE IF EXISTS `alert_record`;

CREATE TABLE `alert_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `greenhouse_id` bigint(20) DEFAULT NULL COMMENT '温室ID',
  `sensor_id` bigint(20) DEFAULT NULL COMMENT '传感器ID',
  `camera_id` bigint(20) DEFAULT NULL COMMENT '摄像头ID',
  `alert_type` varchar(50) NOT NULL COMMENT '告警类型',
  `alert_level` varchar(20) NOT NULL COMMENT '告警级别',
  `trigger_value` decimal(10,2) DEFAULT NULL COMMENT '触发值',
  `message` varchar(500) DEFAULT NULL COMMENT '告警消息',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态: pending/confirmed/resolved',
  `confirmed_by` bigint(20) DEFAULT NULL COMMENT '确认人用户ID',
  `resolution_note` text COMMENT '处理说明',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `confirmed_at` datetime DEFAULT NULL COMMENT '确认时间',
  PRIMARY KEY (`id`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_alert_type` (`alert_type`)
) ENGINE=InnoDB AUTO_INCREMENT=468 DEFAULT CHARSET=utf8 COMMENT='告警记录表';

