/*Table structure for table `alert_rule` */

DROP TABLE IF EXISTS `alert_rule`;

CREATE TABLE `alert_rule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `greenhouse_id` bigint(20) NOT NULL COMMENT '温室ID',
  `alert_type` varchar(50) NOT NULL COMMENT '告警类型: temperature_high/temperature_low/humidity_low/co2_high/light_low',
  `alert_level` varchar(20) NOT NULL COMMENT '告警级别: info/warning/severe/critical',
  `threshold_value` decimal(10,2) NOT NULL COMMENT '阈值',
  `cooldown_minutes` int(11) DEFAULT '30' COMMENT '冷却时间(分钟)',
  `notify_method` varchar(100) DEFAULT 'ui' COMMENT '通知方式: ui,sms,phone逗号分隔',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_alert_type` (`alert_type`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8 COMMENT='告警规则表';

