/*Table structure for table `asset` */

DROP TABLE IF EXISTS `asset`;

CREATE TABLE `asset` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL COMMENT '资产名称',
  `asset_type` varchar(50) NOT NULL COMMENT '资产类型: sensor/actuator/camera/gateway/machine/other',
  `asset_code` varchar(50) DEFAULT NULL COMMENT '资产编号(自动生成)',
  `qr_code` text COMMENT '二维码图片Base64',
  `purchase_date` date DEFAULT NULL COMMENT '采购日期',
  `purchase_amount` decimal(12,2) DEFAULT NULL COMMENT '采购金额',
  `responsible_user_id` bigint(20) DEFAULT NULL COMMENT '负责人用户ID',
  `greenhouse_id` bigint(20) DEFAULT NULL COMMENT '所属温室ID',
  `maintenance_cycle_days` int(11) DEFAULT '90' COMMENT '维保周期(天)',
  `status` varchar(20) NOT NULL DEFAULT 'normal' COMMENT '状态: normal/repairing/scrapped',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_type` (`asset_type`),
  KEY `idx_status` (`status`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_responsible_user` (`responsible_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='资产表';

