/*Table structure for table `detection_record` */

DROP TABLE IF EXISTS `detection_record`;

CREATE TABLE `detection_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `camera_id` bigint(20) NOT NULL COMMENT '摄像头ID',
  `detection_type` varchar(50) NOT NULL COMMENT '检测类型: intruder/animal/pest/device_anomaly',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '置信度',
  `snapshot_path` varchar(500) DEFAULT NULL COMMENT '抓拍图像路径',
  `bbox_json` varchar(500) DEFAULT NULL COMMENT '边界框JSON',
  `is_reviewed` tinyint(1) DEFAULT '0' COMMENT '是否已复核',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `label` varchar(100) DEFAULT NULL COMMENT '检测标签',
  `crop_type` varchar(50) DEFAULT NULL COMMENT '作物类型',
  `greenhouse_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_camera_id` (`camera_id`),
  KEY `idx_detection_type` (`detection_type`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8 COMMENT='AI检测结果表';

