/*Table structure for table `disease` */

DROP TABLE IF EXISTS `disease`;

CREATE TABLE `disease` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '病害名称',
  `disease_type` varchar(50) DEFAULT NULL COMMENT '作物类型',
  `symptoms` text COMMENT '病害症状',
  `pathogen` text COMMENT '发病原因/病原',
  `control_method` text COMMENT '防治方法',
  `image_url` varchar(255) DEFAULT NULL COMMENT '图片URL',
  `greenhouse_id` bigint(20) DEFAULT NULL COMMENT '温室ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COMMENT='病虫害数据库';

/*Data for the table `disease` */

insert  into `disease`(`id`,`name`,`disease_type`,`symptoms`,`pathogen`,`control_method`,`image_url`,`greenhouse_id`,`created_at`,`updated_at`) values (1,'苹果锈病','apple','叶片正面出现橙黄色斑点，后期病斑表面产生毛刺状锈孢子器','苹果锈病真菌侵染，转主寄主为桧柏','清除转主寄主桧柏；萌芽前喷施石硫合剂；发病初期喷施戊唑醇或苯醚甲环唑',NULL,1,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(2,'苹果黑星病','apple','叶片出现圆形放射状黑褐色霉斑，果实表面形成黑色疮痂状病斑','苹果黑星病菌，借风雨传播，多雨年份重发','清除落叶病果；增施有机肥；萌芽前喷施铜制剂；生长期喷施苯醚甲环唑',NULL,1,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(3,'番茄晚疫病','tomato','叶片出现水渍状暗绿色斑点，高湿时叶背产生白色霉层，果实变褐腐烂','致病疫霉菌，低温高湿条件下易于流行','合理密植通风降湿；发病初期喷施霜脲氰或烯酰吗啉；清除病残体',NULL,1,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(4,'番茄灰叶斑病','tomato','叶片出现不规则灰褐色斑点，后期病斑中央灰白色，边缘褐色','番茄灰叶斑病菌，借风雨传播','轮作倒茬；增施钾肥增强抗病性；发病初期喷施苯醚甲环唑或咪鲜胺',NULL,1,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(5,'玉米大斑病','corn','叶片出现长梭形灰绿色至黄褐色大型病斑，后期病斑融合叶片枯焦','玉米大斑病菌，高温高湿条件利于发病','选用抗病品种；合理密植；增施磷钾肥；发病前喷施多菌灵预防',NULL,2,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(6,'玉米灰斑病','corn','叶片出现长方形灰色斑点，后变褐色，严重时叶片枯死','玉米灰斑病菌，借风雨传播','清除病残体；增施有机肥；发病初期喷施苯醚甲环唑或戊唑醇',NULL,2,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(7,'小麦锈病','wheat','叶片或茎秆上出现铁锈色粉状物，分别为条锈、叶锈和秆锈','小麦锈病菌，借气流远距离传播','选用抗病品种；合理施肥避免后期贪青；发病初期喷施戊唑醇或丙环唑',NULL,3,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(8,'黄瓜霜霉病','cucumber','叶片出现多角形淡褐色斑点，叶背产生紫灰色霉层','古巴假霜霉菌，高湿适温条件下流行','通风降湿；合理密植；发病初期喷施霜脲氰或烯酰吗啉',NULL,1,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(9,'水稻纹枯病','rice','叶片或叶鞘出现云纹状褐色斑点，后期病斑融合，植株倒伏','立枯丝核菌，高温高湿利于发病','合理密植避免氮肥过多；浅水灌溉适时烤田；发病初期喷施井冈霉素',NULL,4,'2026-06-17 21:22:39','2026-06-17 21:22:39'),(10,'葡萄霜霉病','grape','叶片出现不规则角斑，背面产生白色霉层，幼果感病变褐腐烂','葡萄霜霉菌，借风雨传播，多雨年份重发','增施有机肥；合理修剪通风透光；发病初期喷施烯酰吗啉',NULL,5,'2026-06-17 21:22:39','2026-06-17 21:22:39');

/*Table structure for table `employee` */

DROP TABLE IF EXISTS `employee`;

CREATE TABLE `employee` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `employee_no` varchar(50) NOT NULL COMMENT '工号',
  `department` varchar(100) DEFAULT NULL COMMENT '部门',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `role_id` bigint(20) DEFAULT NULL COMMENT '角色ID',
  `permission_level` varchar(20) NOT NULL DEFAULT 'staff' COMMENT '权限等级: admin/staff',
  `hire_date` date DEFAULT NULL COMMENT '入职日期',
  `leave_date` date DEFAULT NULL COMMENT '离职日期',
  `id_card` varchar(20) DEFAULT NULL COMMENT '身份证号',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_no` (`employee_no`),
  KEY `idx_department` (`department`),
  KEY `idx_permission_level` (`permission_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='员工表';

/*Data for the table `employee` */

/*Table structure for table `env_data` */

DROP TABLE IF EXISTS `env_data`;

CREATE TABLE `env_data` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `sensor_id` bigint(20) NOT NULL COMMENT '传感器ID',
  `greenhouse_id` bigint(20) NOT NULL COMMENT '温室ID(冗余，加速查询)',
  `temperature` decimal(5,2) DEFAULT NULL COMMENT '温度(℃)',
  `humidity` decimal(5,2) DEFAULT NULL COMMENT '湿度(%RH)',
  `co2` decimal(8,2) DEFAULT NULL COMMENT 'CO2浓度(ppm)',
  `light_intensity` decimal(10,2) DEFAULT NULL COMMENT '光照强度(lux)',
  `recorded_at` datetime NOT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`,`recorded_at`),
  KEY `idx_sensor_recorded` (`sensor_id`,`recorded_at`),
  KEY `idx_greenhouse_recorded` (`greenhouse_id`,`recorded_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4831 DEFAULT CHARSET=utf8 COMMENT='环境时序数据表'
