/*Table structure for table `finance_record` */

DROP TABLE IF EXISTS `finance_record`;

CREATE TABLE `finance_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `record_type` varchar(20) NOT NULL COMMENT '收支类型: expense/income',
  `category` varchar(50) NOT NULL COMMENT '类别: seed/fertilizer/pesticide/water_electricity/equipment/sales/other_income/other_expense',
  `amount` decimal(12,2) NOT NULL COMMENT '金额',
  `record_date` date NOT NULL COMMENT '日期',
  `handler` varchar(50) DEFAULT NULL COMMENT '经办人',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `attachment_url` varchar(500) DEFAULT NULL COMMENT '凭证附件URL',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_record_type` (`record_type`),
  KEY `idx_category` (`category`),
  KEY `idx_record_date` (`record_date`),
  KEY `idx_duplicate` (`amount`,`category`,`record_date`,`handler`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='财务收支表';

/*Data for the table `finance_record` */

/*Table structure for table `greenhouse` */

DROP TABLE IF EXISTS `greenhouse`;

CREATE TABLE `greenhouse` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '温室名称',
  `area` decimal(10,2) DEFAULT NULL COMMENT '面积(亩)',
  `location` varchar(255) DEFAULT NULL COMMENT '位置',
  `crop_type` varchar(50) DEFAULT NULL COMMENT '作物类型',
  `growth_stage` varchar(50) DEFAULT NULL COMMENT '生长阶段: 育苗期/生长期/开花期/结果期/采收期',
  `plant_date` date DEFAULT NULL COMMENT '种植日期',
  `manager` varchar(50) DEFAULT NULL COMMENT '负责人',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='温室表';

/*Data for the table `greenhouse` */

insert  into `greenhouse`(`id`,`name`,`area`,`location`,`crop_type`,`growth_stage`,`plant_date`,`manager`,`created_at`,`updated_at`) values (1,'1号温室','3.00','A区东侧','番茄','结果期','2026-03-15','张主管','2026-06-11 11:22:35','2026-06-11 11:22:35'),(2,'2号温室','2.50','A区西侧','黄瓜','开花期','2026-04-01','张主管','2026-06-11 11:22:35','2026-06-11 11:22:35'),(3,'3号温室','4.00','B区东侧','辣椒','生长期','2026-05-10','李主管','2026-06-11 11:22:35','2026-06-11 11:22:35'),(4,'4号温室','3.50','B区西侧','草莓','采收期','2026-02-20','李主管','2026-06-11 11:22:35','2026-06-11 11:22:35'),(5,'5号温室','5.00','C区','玉米','育苗期','2026-06-01','王主管','2026-06-11 11:22:35','2026-06-11 11:22:35');

/*Table structure for table `knowledge_entry` */

DROP TABLE IF EXISTS `knowledge_entry`;

CREATE TABLE `knowledge_entry` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL COMMENT '标题',
  `category` varchar(50) NOT NULL COMMENT '分类: 种植技术/病虫害防治/施肥管理/灌溉技术/温控管理',
  `content` text NOT NULL COMMENT '内容',
  `source` varchar(255) DEFAULT NULL COMMENT '来源',
  `review_status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '审核状态: draft/reviewed/published',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_review_status` (`review_status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COMMENT='知识条目表';

/*Data for the table `knowledge_entry` */

insert  into `knowledge_entry`(`id`,`title`,`category`,`content`,`source`,`review_status`,`created_at`,`updated_at`) values (1,'番茄常见病虫害防治指南','病虫害防治','番茄常见病害包括晚疫病、早疫病、叶霉病等。晚疫病可用霜脲·锰锌防治，早疫病可用苯醚甲环唑，叶霉病可用嘧菌酯。虫害主要有白粉虱、蚜虫，可用吡虫啉或啶虫脒防治。','农业种植知识库','published','2026-06-11 11:22:35','2026-06-11 11:22:35'),(2,'温室黄瓜水肥管理技术','施肥管理','黄瓜生长期需保持土壤湿润，相对湿度控制在70%-85%。追肥以氮钾肥为主，每7-10天一次。结果期增加磷钾肥比例，促进果实发育。','中国农业科学院','published','2026-06-11 11:22:35','2026-06-11 11:22:35'),(3,'温室冬季保温措施','温控管理','冬季保温措施：1. 检查棚膜完整性，修补破损；2. 夜间加盖保温被；3. 必要时启用加热设备，保持夜间温度不低于12℃；4. 晴天白天适时通风降湿。','农业气象网','published','2026-06-11 11:22:35','2026-06-11 11:22:35'),(4,'滴灌系统维护与故障排查','灌溉技术','定期清洗过滤器（每周1次）、检查滴头是否堵塞、主管道是否有漏水点。冬季停用前需排空管道积水防冻裂。常见故障：滴头不出水（堵塞）→ 酸洗或更换；管道压力不足 → 检查水泵和阀门。','农业种植知识库','reviewed','2026-06-11 11:22:35','2026-06-11 11:22:35');

/*Table structure for table `knowledge_push_record` */

DROP TABLE IF EXISTS `knowledge_push_record`;

CREATE TABLE `knowledge_push_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `entry_id` bigint(20) NOT NULL COMMENT '知识条目ID',
  `target_user_id` bigint(20) NOT NULL COMMENT '目标用户ID',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '是否已读',
  `pushed_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `read_at` datetime DEFAULT NULL COMMENT '阅读时间',
  PRIMARY KEY (`id`),
  KEY `idx_target_user` (`target_user_id`),
  KEY `idx_entry_id` (`entry_id`),
  KEY `idx_is_read` (`is_read`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='知识推送记录表';

/*Data for the table `knowledge_push_record` */

/*Table structure for table `report` */

DROP TABLE IF EXISTS `report`;

CREATE TABLE `report` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `report_type` varchar(50) NOT NULL COMMENT '报表类型: finance/planting',
  `period_start` date DEFAULT NULL COMMENT '统计起始日期',
  `period_end` date DEFAULT NULL COMMENT '统计截止日期',
  `file_url` varchar(500) DEFAULT NULL COMMENT '报表文件URL',
  `greenhouse_id` bigint(20) DEFAULT NULL COMMENT '温室ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_report_type` (`report_type`),
  KEY `idx_period` (`period_start`,`period_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='报表表';

/*Data for the table `report` */

/*Table structure for table `sensor` */

DROP TABLE IF EXISTS `sensor`;

CREATE TABLE `sensor` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `greenhouse_id` bigint(20) NOT NULL COMMENT '所属温室ID',
  `sensor_type` varchar(50) NOT NULL COMMENT '传感器类型: temperature/humidity/co2/light',
  `model` varchar(100) DEFAULT NULL COMMENT '型号: SHT30/MH-Z19/BH1750',
  `device_sn` varchar(100) DEFAULT NULL COMMENT '设备序列号',
  `install_position` varchar(255) DEFAULT NULL COMMENT '安装位置',
  `status` varchar(20) NOT NULL DEFAULT 'running' COMMENT '状态: running/offline/fault',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_greenhouse_id` (`greenhouse_id`),
  KEY `idx_sensor_type` (`sensor_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8 COMMENT='传感器表';

